using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using ResearchAgent;

var builder = Host.CreateApplicationBuilder(args);
builder.Configuration.AddEnvironmentVariables();

builder.Services.AddSingleton<Notepad>();

builder.Services.AddChatClient(chatClientBuilder =>
    chatClientBuilder.UseOpenAIChatClient(
        builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18"));

builder.Services.AddSingleton(sp =>
{
    var chatClient = sp.GetRequiredService<IChatClient>();
    var notepad = sp.GetRequiredService<Notepad>();

    var tools = new AITool[]
    {
        AIFunctionFactory.Create(
            ([Description("The search query")] string query) =>
            {
                var logger = sp.GetRequiredService<ILoggerFactory>().CreateLogger("WebSearch");
                logger.LogInformation("Searching web for: {Query}", query);

                // Simulated web search results — swap with a real search API in production
                var results = WebSearchSimulator.Search(query);
                return results;
            },
            new AIFunctionFactoryOptions
            {
                Name = "web_search",
                Description = "Search the web for information on a topic. Returns relevant snippets.",
            }),

        AIFunctionFactory.Create(
            ([Description("Title for the note")] string title,
             [Description("Content of the note")] string content) =>
            {
                notepad.AddNote(title, content);
                return $"Note saved: '{title}'";
            },
            new AIFunctionFactoryOptions
            {
                Name = "take_note",
                Description = "Save a research note with a title and content for later reference.",
            }),

        AIFunctionFactory.Create(
            () => notepad.GetAllNotes(),
            new AIFunctionFactoryOptions
            {
                Name = "read_notes",
                Description = "Read all previously saved research notes.",
            }),
    };

    var instructions = """
        You are a research agent. Your job is to research a topic thoroughly and produce a summary.

        Follow this workflow:
        1. Break the topic into 2-3 key subtopics or questions.
        2. Use the web_search tool to find information for each subtopic.
        3. Use the take_note tool to save important findings as you go.
        4. After gathering enough information, use read_notes to review your notes.
        5. Produce a well-structured summary with sections, citing the sources you found.

        Be thorough but concise. Focus on factual, well-sourced information.
        """;

    return new ChatClientAgent(chatClient, instructions, name: "ResearchAgent",
        description: "Researches topics using web search and note-taking", tools: tools);
});

using var host = builder.Build();

var agent = host.Services.GetRequiredService<ChatClientAgent>();
var notepad = host.Services.GetRequiredService<Notepad>();

Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║        AI Research Agent                 ║");
Console.WriteLine("║  Type a topic to research, or 'quit'.   ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.Write("Research topic> ");
    var topic = Console.ReadLine()?.Trim();

    if (string.IsNullOrEmpty(topic))
        continue;

    if (topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notepad.Clear();

    Console.WriteLine();
    Console.WriteLine($"Researching: {topic}");
    Console.WriteLine(new string('─', 50));

    try
    {
        var runOptions = new ChatClientAgentRunOptions(new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
        });

        var response = await agent.RunAsync(
            $"Research the following topic and provide a comprehensive summary: {topic}",
            options: runOptions);

        Console.WriteLine();
        Console.WriteLine(response.Text);
    }
    catch (Exception ex)
    {
        Console.WriteLine($"Error: {ex.Message}");
    }

    Console.WriteLine();
    Console.WriteLine(new string('═', 50));
    Console.WriteLine();
}

