namespace ResearchAgent;

/// <summary>
/// Thread-safe notepad for the research agent to store findings.
/// </summary>
public sealed class Notepad
{
    private readonly List<(string Title, string Content, DateTime Timestamp)> _notes = [];
    private readonly Lock _lock = new();

    public void AddNote(string title, string content)
    {
        lock (_lock)
        {
            _notes.Add((title, content, DateTime.UtcNow));
        }
    }

    public string GetAllNotes()
    {
        lock (_lock)
        {
            if (_notes.Count == 0)
                return "No notes saved yet.";

            return string.Join("\n\n", _notes.Select((n, i) =>
                $"[Note {i + 1}] {n.Title}\n{n.Content}"));
        }
    }

    public void Clear()
    {
        lock (_lock)
        {
            _notes.Clear();
        }
    }
}

