/// <summary>
/// Simulates web search results for demonstration purposes.
/// Replace with a real search API (e.g., Bing Search, Google Custom Search) in production.
/// </summary>
public static class WebSearchSimulator
{
    private static readonly Dictionary<string, List<SearchResult>> TopicResults = new(StringComparer.OrdinalIgnoreCase)
    {
        ["artificial intelligence"] =
        [
            new("History of AI - Wikipedia", "https://en.wikipedia.org/wiki/AI",
                "Artificial intelligence was founded as an academic discipline in 1956. The field experienced several waves of optimism, followed by disappointment and loss of funding (known as 'AI winters'), followed by new approaches, success, and renewed funding."),
            new("What is AI? - IBM", "https://www.ibm.com/think/topics/artificial-intelligence",
                "Artificial intelligence leverages computers and machines to mimic the problem-solving and decision-making capabilities of the human mind. It encompasses machine learning, deep learning, and natural language processing."),
            new("AI Applications in 2025 - MIT Technology Review", "https://www.technologyreview.com/ai-2025",
                "AI is transforming healthcare diagnostics, autonomous vehicles, financial trading, and creative industries. Large language models have become the fastest-adopted technology in history."),
        ],
        ["climate change"] =
        [
            new("Climate Change Evidence - NASA", "https://climate.nasa.gov/evidence",
                "Global temperature has risen about 1.1°C since the late 1800s. The ocean has absorbed much of this increased heat, with the top 100 meters warming more than 0.6°F since 1969."),
            new("IPCC Sixth Assessment Report", "https://www.ipcc.ch/report/ar6",
                "Human activities, principally through emissions of greenhouse gases, have unequivocally caused global warming. Global surface temperature has increased faster since 1970 than in any other 50-year period over at least the last 2000 years."),
            new("Climate Solutions - Project Drawdown", "https://drawdown.org",
                "Top solutions include reducing food waste, shifting to plant-rich diets, improving clean cookstoves, expanding onshore and offshore wind, and restoring tropical forests. Collectively these could reduce over 1,000 gigatons of CO2."),
        ],
        ["quantum computing"] =
        [
            new("Quantum Computing Fundamentals - Nature", "https://www.nature.com/quantum-computing",
                "Quantum computers use quantum bits (qubits) that can exist in superposition states. This allows them to process vast numbers of possibilities simultaneously, potentially solving problems intractable for classical computers."),
            new("Quantum Advantage Achieved - Google AI Blog", "https://ai.googleblog.com/quantum",
                "In recent experiments, quantum processors have demonstrated computational tasks that would take classical supercomputers thousands of years. This milestone is known as 'quantum advantage' or 'quantum supremacy'."),
            new("Quantum Computing Applications - McKinsey", "https://www.mckinsey.com/quantum-computing",
                "Industries poised to benefit include pharmaceuticals (drug discovery), finance (portfolio optimization), logistics (route optimization), and materials science (new material design). The market is projected to reach $850B by 2040."),
        ],
    };

    public static string Search(string query)
    {
        // Find the best matching topic
        var results = TopicResults
            .Where(kv => query.Contains(kv.Key, StringComparison.OrdinalIgnoreCase)
                         || kv.Key.Contains(query, StringComparison.OrdinalIgnoreCase))
            .SelectMany(kv => kv.Value)
            .ToList();

        if (results.Count == 0)
        {
            // Generate generic results for unknown topics
            results =
            [
                new($"{query} - Overview", $"https://en.wikipedia.org/wiki/{Uri.EscapeDataString(query)}",
                    $"{query} is a broad topic with many aspects to explore. Key areas include its history, current state, and future implications."),
                new($"Latest Research on {query}", $"https://scholar.google.com/search?q={Uri.EscapeDataString(query)}",
                    $"Recent academic research on {query} has produced significant findings across multiple disciplines. Peer-reviewed studies continue to expand our understanding."),
                new($"{query} - Practical Applications", $"https://www.example.com/{Uri.EscapeDataString(query)}",
                    $"The practical applications of {query} span industry, education, and daily life. Adoption continues to grow as the technology and understanding mature."),
            ];
        }

        return string.Join("\n\n", results.Select(r =>
            $"**{r.Title}**\nSource: {r.Url}\n{r.Snippet}"));
    }

    private sealed record SearchResult(string Title, string Url, string Snippet);
}

